// Generates src/lib/tool-registry/public-manifest.generated.ts from the
// validated tool registry. The generated file is the ONLY registry-derived
// module the browser bundle imports - it contains only display + capability
// status, never paths, reader keys, env names, resume commands, or pricing.
//
// Run: npm run generate:manifest   (also runs in prebuild and verify:tool-registry)
import { tsImport } from "tsx/esm/api";
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");

const registryMod = await tsImport(
  join(root, "src/lib/tool-registry/registry.ts"),
  import.meta.url,
);
const manifestMod = await tsImport(
  join(root, "src/lib/tool-registry/manifest.ts"),
  import.meta.url,
);

const { compileToolRegistry } = registryMod;
const { generatePublicManifest, manifestIsSafe } = manifestMod;
const { TOOL_DEFINITIONS } = await tsImport(
  join(root, "src/lib/tool-registry/tools/index.ts"),
  import.meta.url,
);

const registry = compileToolRegistry(TOOL_DEFINITIONS);
if (registry.diagnostics.length > 0) {
  console.error("Registry validation failed:");
  for (const d of registry.diagnostics) {
    console.error(`  [${d.severity}] ${d.toolId}: ${d.code} - ${d.message}`);
  }
  process.exit(1);
}

const manifest = generatePublicManifest(TOOL_DEFINITIONS);
if (!manifestIsSafe(manifest)) {
  console.error(
    "Generated manifest failed safety check (leaks sensitive fields).",
  );
  process.exit(1);
}

const outPath = join(
  root,
  "src/lib/tool-registry/public-manifest.generated.ts",
);
const banner =
  "// @generated by scripts/generate-tool-manifest.mjs — DO NOT EDIT.\n";
const body = `import type { PublicToolManifest } from "./manifest.ts";\n\nexport const PUBLIC_TOOL_MANIFEST: PublicToolManifest = ${JSON.stringify(manifest, null, 2)};\n`;
await writeFile(outPath, banner + body, "utf8");
console.log(`Wrote ${outPath} (${manifest.tools.length} tools).`);
